  var CAR = [
    {
      id: 'car_no_start_crank', v: '4w', icon: '🔋',
      name: m('Won\'t start — no crank / just a click', 'स्टार्ट नहीं हो रही — क्रैंक नहीं / सिर्फ़ क्लिक', 'ஸ்டார்ட் ஆகவில்லை — க்ரேங்க் இல்லை / வெறும் கிளிக்', 'స్టార్ట్ కావడం లేదు — క్రాంక్ లేదు / కేవలం క్లిక్', 'স্টার্ট হচ্ছে না — ক্র্যাঙ্ক নেই / শুধু ক্লিক', 'सुरू होत नाही — क्रँक नाही / फक्त क्लिक', 'સ્ટાર્ટ થતી નથી — ક્રેન્ક નહીં / માત્ર ક્લિક', 'ಸ್ಟಾರ್ಟ್ ಆಗುತ್ತಿಲ್ಲ — ಕ್ರ್ಯಾಂಕ್ ಇಲ್ಲ / ಕೇವಲ ಕ್ಲಿಕ್', 'സ്റ്റാർട്ട് ആകുന്നില്ല — ക്രാങ്ക് ഇല്ല / വെറും ക്ലിക്ക്'),
      safety: { red: false, warn: m('Park brake on, gear in P (auto) or neutral (manual) for every check.', 'हर जाँच के लिए पार्क ब्रेक लगाएँ, गियर P (ऑटो) या न्यूट्रल (मैनुअल) में रखें।', 'ஒவ்வொரு சோதனைக்கும் பார்க் பிரேக் போடுங்கள், கியர் P (ஆட்டோ) அல்லது நியூட்ரல் (மேனுவல்) இல் வைக்கவும்.', 'ప్రతి తనిఖీకి పార్క్ బ్రేక్ వేయండి, గేర్ P (ఆటో) లేదా న్యూట్రల్ (మాన్యువల్) లో ఉంచండి.', 'প্রতিটি চেকের জন্য পার্ক ব্রেক দিন, গিয়ার P (অটো) বা নিউট্রাল (ম্যানুয়াল)-এ রাখুন।', 'प्रत्येक तपासणीसाठी पार्क ब्रेक लावा, गिअर P (ऑटो) किंवा न्यूट्रल (मॅन्युअल) मध्ये ठेवा.', 'દરેક ચેક માટે પાર્ક બ્રેક લગાવો, ગિયર P (ઓટો) કે ન્યૂટ્રલ (મેન્યુઅલ) માં રાખો.', 'ಪ್ರತಿ ಪರಿಶೀಲನೆಗೆ ಪಾರ್ಕ್ ಬ್ರೇಕ್ ಹಾಕಿ, ಗೇರ್ P (ಆಟೋ) ಅಥವಾ ನ್ಯೂಟ್ರಲ್ (ಮ್ಯಾನುಯಲ್) ನಲ್ಲಿ ಇಡಿ.', 'ഓരോ പരിശോധനയ്ക്കും പാർക്ക് ബ്രേക്ക് ഇടുക, ഗിയർ P (ഓട്ടോ) അല്ലെങ്കിൽ ന്യൂട്രൽ (മാനുവൽ) ൽ വയ്ക്കുക.') },
      causes: [
        { name: m('Not in P / N (auto), or clutch not pressed (manual)', 'P/N में नहीं (ऑटो), या क्लच नहीं दबा (मैनुअल)', 'P / N இல் இல்லை (ஆட்டோ), அல்லது கிளட்ச் அழுத்தப்படவில்லை (மேனுவல்)', 'P / N లో లేదు (ఆటో), లేదా క్లచ్ నొక్కలేదు (మాన్యువల్)', 'P / N-এ নেই (অটো), বা ক্লাচ চাপা হয়নি (ম্যানুয়াল)', 'P / N मध्ये नाही (ऑटो), किंवा क्लच दाबला नाही (मॅन्युअल)', 'P / N માં નથી (ઓટો), કે ક્લચ દબાવ્યો નથી (મેન્યુઅલ)', 'P / N ನಲ್ಲಿ ಇಲ್ಲ (ಆಟೋ), ಅಥವಾ ಕ್ಲಚ್ ಒತ್ತಿಲ್ಲ (ಮ್ಯಾನುಯಲ್)', 'P / N ൽ അല്ല (ഓട്ടോ), അല്ലെങ്കിൽ ക്ലച്ച് അമർത്തിയിട്ടില്ല (മാനുവൽ)'), pct: 15, tier: 'green', diff: 1, timeMin: 1,
          tools: m('None', 'कुछ नहीं', 'எதுவும் இல்லை', 'ఏమీ లేదు', 'কিছু না', 'काहीही नाही', 'કંઈ નહીં', 'ಏನೂ ಇಲ್ಲ', 'ഒന്നുമില്ല'),
          check: m('Auto cars only start in P or N; many manuals need the clutch fully pressed.', 'ऑटो कार सिर्फ़ P या N में स्टार्ट होती है; कई मैनुअल में क्लच पूरा दबाना पड़ता है।', 'ஆட்டோ கார்கள் P அல்லது N இல் மட்டுமே ஸ்டார்ட் ஆகும்; பல மேனுவல்களில் கிளட்சை முழுவதும் அழுத்த வேண்டும்.', 'ఆటో కార్లు P లేదా N లో మాత్రమే స్టార్ట్ అవుతాయి; చాలా మాన్యువల్‌లకు క్లచ్ పూర్తిగా నొక్కాలి.', 'অটো কার শুধু P বা N-এ স্টার্ট হয়; অনেক ম্যানুয়ালে ক্লাচ পুরো চাপতে হয়।', 'ऑटो कार फक्त P किंवा N मध्ये सुरू होतात; अनेक मॅन्युअलमध्ये क्लच पूर्ण दाबावा लागतो.', 'ઓટો કાર માત્ર P કે N માં સ્ટાર્ટ થાય; ઘણી મેન્યુઅલમાં ક્લચ પૂરો દબાવવો પડે.', 'ಆಟೋ ಕಾರ್‌ಗಳು P ಅಥವಾ N ನಲ್ಲಿ ಮಾತ್ರ ಸ್ಟಾರ್ಟ್ ಆಗುತ್ತವೆ; ಹಲವು ಮ್ಯಾನುಯಲ್‌ಗಳಲ್ಲಿ ಕ್ಲಚ್ ಪೂರ್ತಿ ಒತ್ತಬೇಕು.', 'ഓട്ടോ കാറുകൾ P അല്ലെങ്കിൽ N ൽ മാത്രമേ സ്റ്റാർട്ട് ആകൂ; പല മാനുവലുകളിലും ക്ലച്ച് പൂർണമായി അമർത്തണം.'),
          steps: [ m('Auto: move the lever firmly to P, then start. Manual: press the clutch fully.', 'ऑटो: लीवर को P पर करें, फिर स्टार्ट। मैनुअल: क्लच पूरा दबाएँ।', 'ஆட்டோ: லீவரை உறுதியாக P க்கு நகர்த்தி, பிறகு ஸ்டார்ட் செய்யுங்கள். மேனுவல்: கிளட்சை முழுவதும் அழுத்துங்கள்.', 'ఆటో: లీవర్‌ను గట్టిగా P కు జరిపి, తర్వాత స్టార్ట్ చేయండి. మాన్యువల్: క్లచ్ పూర్తిగా నొక్కండి.', 'অটো: লিভারটি শক্ত করে P-তে নিন, তারপর স্টার্ট করুন। ম্যানুয়াল: ক্লাচ পুরো চাপুন।', 'ऑटो: लीव्हर ठामपणे P वर हलवा, मग सुरू करा. मॅन्युअल: क्लच पूर्ण दाबा.', 'ઓટો: લીવરને મજબૂતીથી P પર લઈ જાઓ, પછી સ્ટાર્ટ કરો. મેન્યુઅલ: ક્લચ પૂરો દબાવો.', 'ಆಟೋ: ಲೀವರ್ ಅನ್ನು ಗಟ್ಟಿಯಾಗಿ P ಗೆ ಸರಿಸಿ, ನಂತರ ಸ್ಟಾರ್ಟ್ ಮಾಡಿ. ಮ್ಯಾನುಯಲ್: ಕ್ಲಚ್ ಪೂರ್ತಿ ಒತ್ತಿ.', 'ഓട്ടോ: ലിവർ ഉറപ്പിച്ച് P ലേക്ക് നീക്കുക, പിന്നെ സ്റ്റാർട്ട് ചെയ്യുക. മാനുവൽ: ക്ലച്ച് പൂർണമായി അമർത്തുക.') ],
          ifFails: m('Still a click / nothing? It\'s the battery.', 'फिर भी क्लिक / कुछ नहीं? बैटरी है।', 'இன்னும் கிளிக் / ஒன்றுமில்லையா? பேட்டரிதான்.', 'ఇప్పటికీ క్లిక్ / ఏమీ లేదా? బ్యాటరీయే.', 'এখনও ক্লিক / কিছু না? এটা ব্যাটারি।', 'अजूनही क्लिक / काही नाही? बॅटरीच आहे.', 'હજુ ક્લિક / કંઈ નહીં? એ બેટરી છે.', 'ಇನ್ನೂ ಕ್ಲಿಕ್ / ಏನೂ ಇಲ್ಲವೇ? ಬ್ಯಾಟರಿಯೇ.', 'ഇപ്പോഴും ക്ലിക്ക് / ഒന്നുമില്ലേ? അത് ബാറ്ററിയാണ്.'), mechCost: '₹0' },
        { name: m('Flat / loose battery → jump start', 'बैटरी डिस्चार्ज / ढीली → जंप स्टार्ट', 'பேட்டரி டிஸ்சார்ஜ் / தளர்வு → ஜம்ப் ஸ்டார்ட்', 'బ్యాటరీ డిస్చార్జ్ / వదులు → జంప్ స్టార్ట్', 'ব্যাটারি ডিসচার্জ / ঢিলে → জাম্প স্টার্ট', 'बॅटरी डिस्चार्ज / सैल → जंप स्टार्ट', 'બેટરી ડિસ્ચાર્જ / ઢીલી → જમ્પ સ્ટાર્ટ', 'ಬ್ಯಾಟರಿ ಡಿಸ್ಚಾರ್ಜ್ / ಸಡಿಲ → ಜಂಪ್ ಸ್ಟಾರ್ಟ್', 'ബാറ്ററി ഡിസ്ചാർജ് / അയഞ്ഞത് → ജംപ് സ്റ്റാർട്ട്'), pct: 55, tier: 'amber', diff: 4, timeMin: 15,
          tools: m('Jumper cables + another car, or a jump pack', 'जम्पर केबल + दूसरी कार, या जंप पैक', 'ஜம்பர் கேபிள் + இன்னொரு கார், அல்லது ஜம்ப் பேக்', 'జంపర్ కేబుల్స్ + మరో కారు, లేదా జంప్ ప్యాక్', 'জাম্পার কেবল + আরেকটি গাড়ি, বা জাম্প প্যাক', 'जम्पर केबल + दुसरी कार, किंवा जंप पॅक', 'જમ્પર કેબલ + બીજી કાર, કે જમ્પ પેક', 'ಜಂಪರ್ ಕೇಬಲ್ + ಮತ್ತೊಂದು ಕಾರು, ಅಥವಾ ಜಂಪ್ ಪ್ಯಾಕ್', 'ജംപർ കേബിളുകൾ + മറ്റൊരു കാർ, അല്ലെങ്കിൽ ജംപ് പാക്ക്'),
          check: m('Dashboard dim, single click, lights weak? Flat battery — the #1 car no-start.', 'डैश मद्धम, एक क्लिक, लाइट कमज़ोर? बैटरी डिस्चार्ज — कार का #1 no-start।', 'டாஷ்போர்டு மங்கலாக, ஒரு கிளிக், விளக்குகள் பலவீனமா? பேட்டரி டிஸ்சார்ஜ் — காரின் #1 no-start.', 'డాష్‌బోర్డ్ మసకగా, ఒక క్లిక్, లైట్లు బలహీనమా? బ్యాటరీ డిస్చార్జ్ — కారు #1 no-start.', 'ড্যাশবোর্ড ম্লান, একটি ক্লিক, লাইট দুর্বল? ব্যাটারি ডিসচার্জ — গাড়ির #1 no-start।', 'डॅशबोर्ड मंद, एक क्लिक, दिवे कमजोर? बॅटरी डिस्चार्ज — कारचा #1 no-start.', 'ડેશબોર્ડ ઝાંખું, એક ક્લિક, લાઇટ નબળી? બેટરી ડિસ્ચાર્જ — કારનો #1 no-start.', 'ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ ಮಂದ, ಒಂದು ಕ್ಲಿಕ್, ಲೈಟ್ ದುರ್ಬಲ? ಬ್ಯಾಟರಿ ಡಿಸ್ಚಾರ್ಜ್ — ಕಾರಿನ #1 no-start.', 'ഡാഷ്‌ബോർഡ് മങ്ങിയത്, ഒരു ക്ലിക്ക്, ലൈറ്റുകൾ ദുർബലം? ബാറ്ററി ഡിസ്ചാർജ് — കാറിന്റെ #1 no-start.'),
          steps: [ m('Both cars OFF. RED clamp to dead +, other RED to good +.', 'दोनों कारें बंद। लाल क्लैंप खराब + पर, दूसरा लाल अच्छी + पर।', 'இரண்டு கார்களும் OFF. சிவப்பு கிளாம்ப் டெட் + இல், மற்ற சிவப்பு நல்ல + இல்.', 'రెండు కార్లు OFF. ఎరుపు క్లాంప్ చనిపోయిన + కు, మరో ఎరుపు మంచి + కు.', 'দুটি গাড়ি OFF। লাল ক্ল্যাম্প ডেড +-এ, অন্য লাল ভালো +-এ।', 'दोन्ही कार OFF. लाल क्लॅम्प डेड + वर, दुसरा लाल चांगल्या + वर.', 'બંને કાર OFF. લાલ ક્લેમ્પ ડેડ + પર, બીજો લાલ સારી + પર.', 'ಎರಡೂ ಕಾರ್ OFF. ಕೆಂಪು ಕ್ಲಾಂಪ್ ಡೆಡ್ + ಗೆ, ಮತ್ತೊಂದು ಕೆಂಪು ಒಳ್ಳೆಯ + ಗೆ.', 'രണ്ട് കാറുകളും OFF. ചുവന്ന ക്ലാമ്പ് ഡെഡ് + ലേക്ക്, മറ്റേ ചുവന്നത് നല്ല + ലേക്ക്.'), m('BLACK to good −, other BLACK to bare metal on the dead car (not the battery).', 'काला अच्छी − पर, दूसरा काला खराब कार की नंगी धातु पर (बैटरी पर नहीं)।', 'கருப்பு நல்ல − இல், மற்ற கருப்பு டெட் காரின் வெறும் உலோகத்தில் (பேட்டரியில் அல்ல).', 'నలుపు మంచి − కు, మరో నలుపు చనిపోయిన కారు ఖాళీ లోహానికి (బ్యాటరీకి కాదు).', 'কালো ভালো −-এ, অন্য কালো ডেড গাড়ির খালি ধাতুতে (ব্যাটারিতে নয়)।', 'काळा चांगल्या − वर, दुसरा काळा डेड कारच्या उघड्या धातूवर (बॅटरीवर नाही).', 'કાળો સારી − પર, બીજો કાળો ડેડ કારની ખુલ્લી ધાતુ પર (બેટરી પર નહીં).', 'ಕಪ್ಪು ಒಳ್ಳೆಯ − ಗೆ, ಮತ್ತೊಂದು ಕಪ್ಪು ಡೆಡ್ ಕಾರಿನ ಬರಿಯ ಲೋಹಕ್ಕೆ (ಬ್ಯಾಟರಿಗೆ ಅಲ್ಲ).', 'കറുപ്പ് നല്ല − ലേക്ക്, മറ്റേ കറുപ്പ് ഡെഡ് കാറിന്റെ ലോഹഭാഗത്തേക്ക് (ബാറ്ററിയിലല്ല).'), m('Start the good car, wait 2 min, then start the dead car.', 'अच्छी कार स्टार्ट करें, 2 मिनट रुकें, फिर खराब कार स्टार्ट करें।', 'நல்ல காரை ஸ்டார்ட் செய்து, 2 நிமிடம் காத்திருந்து, பிறகு டெட் காரை ஸ்டார்ட் செய்யுங்கள்.', 'మంచి కారును స్టార్ట్ చేసి, 2 నిమిషాలు ఆగి, తర్వాత చనిపోయిన కారును స్టార్ట్ చేయండి.', 'ভালো গাড়ি স্টার্ট করুন, 2 মিনিট অপেক্ষা করুন, তারপর ডেড গাড়ি স্টার্ট করুন।', 'चांगली कार सुरू करा, 2 मिनिटे थांबा, मग डेड कार सुरू करा.', 'સારી કાર સ્ટાર્ટ કરો, 2 મિનિટ રાહ જુઓ, પછી ડેડ કાર સ્ટાર્ટ કરો.', 'ಒಳ್ಳೆಯ ಕಾರು ಸ್ಟಾರ್ಟ್ ಮಾಡಿ, 2 ನಿಮಿಷ ಕಾಯಿರಿ, ನಂತರ ಡೆಡ್ ಕಾರು ಸ್ಟಾರ್ಟ್ ಮಾಡಿ.', 'നല്ല കാർ സ്റ്റാർട്ട് ചെയ്യുക, 2 മിനിറ്റ് കാത്തിരുന്ന്, പിന്നെ ഡെഡ് കാർ സ്റ്റാർട്ട് ചെയ്യുക.'), m('Remove cables in reverse order. Keep the engine running 20 min.', 'केबल उल्टे क्रम में हटाएँ। इंजन 20 मिनट चालू रखें।', 'கேபிள்களை தலைகீழ் வரிசையில் கழற்றுங்கள். இன்ஜினை 20 நிமிடம் ஓடவிடுங்கள்.', 'కేబుల్స్‌ను రివర్స్ క్రమంలో తీయండి. ఇంజిన్‌ను 20 నిమిషాలు నడిపించండి.', 'কেবল উল্টো ক্রমে খুলুন। ইঞ্জিন 20 মিনিট চালু রাখুন।', 'केबल उलट्या क्रमाने काढा. इंजिन 20 मिनिटे चालू ठेवा.', 'કેબલ ઊલટા ક્રમમાં કાઢો. એન્જિન 20 મિનિટ ચાલુ રાખો.', 'ಕೇಬಲ್‌ಗಳನ್ನು ಹಿಮ್ಮುಖ ಕ್ರಮದಲ್ಲಿ ತೆಗೆಯಿರಿ. ಇಂಜಿನ್ ಅನ್ನು 20 ನಿಮಿಷ ಚಾಲನೆಯಲ್ಲಿಡಿ.', 'കേബിളുകൾ വിപരീത ക്രമത്തിൽ ഊരുക. എഞ്ചിൻ 20 മിനിറ്റ് ഓടിക്കുക.') ],
          ifFails: m('No jump after 2 tries → starter or deeper fault. Tow it.', '2 बार में जंप न हो → स्टार्टर या गहरी खराबी। टो करें।', '2 முறை முயற்சித்தும் ஜம்ப் ஆகவில்லையா → ஸ்டார்ட்டர் அல்லது ஆழமான கோளாறு. டோ செய்யுங்கள்.', '2 సార్లు ప్రయత్నించినా జంప్ కాలేదా → స్టార్టర్ లేదా లోతైన లోపం. టో చేయండి.', '2 বার চেষ্টার পরও জাম্প না → স্টার্টার বা গভীর ত্রুটি। টো করুন।', '2 वेळा प्रयत्न करूनही जंप नाही → स्टार्टर किंवा खोल बिघाड. टो करा.', '2 વાર પ્રયત્ન છતાં જમ્પ નહીં → સ્ટાર્ટર કે ઊંડી ખામી. ટો કરો.', '2 ಬಾರಿ ಪ್ರಯತ್ನಿಸಿದರೂ ಜಂಪ್ ಆಗಿಲ್ಲವೇ → ಸ್ಟಾರ್ಟರ್ ಅಥವಾ ಆಳವಾದ ದೋಷ. ಟೋ ಮಾಡಿ.', '2 തവണ ശ്രമിച്ചിട്ടും ജംപ് ആയില്ലേ → സ്റ്റാർട്ടർ അല്ലെങ്കിൽ ആഴത്തിലുള്ള തകരാർ. ടോ ചെയ്യുക.'), mechCost: '₹0 (jump) / ₹3,000–₹8,000 (battery)' },
        { name: m('Corroded / loose battery terminal', 'बैटरी टर्मिनल जंग / ढीला', 'பேட்டரி டெர்மினல் துருப்பிடித்த / தளர்வான', 'బ్యాటరీ టర్మినల్ తుప్పు / వదులు', 'ব্যাটারি টার্মিনাল মরিচা / ঢিলে', 'बॅटरी टर्मिनल गंज / सैल', 'બેટરી ટર્મિનલ કાટ / ઢીલું', 'ಬ್ಯಾಟರಿ ಟರ್ಮಿನಲ್ ತುಕ್ಕು / ಸಡಿಲ', 'ബാറ്ററി ടെർമിനൽ തുരുമ്പ് / അയഞ്ഞത്'), pct: 20, tier: 'amber', diff: 3, timeMin: 10,
          tools: m('Spanner (10mm), cloth', 'पाना (10mm), कपड़ा', 'ஸ்பேனர் (10mm), துணி', 'స్పానర్ (10mm), గుడ్డ', 'স্প্যানার (10mm), কাপড়', 'पाना (10mm), कापड', 'સ્પેનર (10mm), કપડું', 'ಸ್ಪ್ಯಾನರ್ (10mm), ಬಟ್ಟೆ', 'സ്പാനർ (10mm), തുണി'),
          check: m('White/green powder on the terminals? Clean and tighten before jumping.', 'टर्मिनल पर सफ़ेद/हरा पाउडर? जंप से पहले साफ़ और कसें।', 'டெர்மினல்களில் வெள்ளை/பச்சை பவுடரா? ஜம்ப் செய்வதற்கு முன் சுத்தம் செய்து இறுக்குங்கள்.', 'టర్మినల్స్‌పై తెలుపు/ఆకుపచ్చ పొడిగా? జంప్ చేయడానికి ముందు శుభ్రం చేసి బిగించండి.', 'টার্মিনালে সাদা/সবুজ পাউডার? জাম্প করার আগে পরিষ্কার করে শক্ত করুন।', 'टर्मिनलवर पांढरी/हिरवी पावडर? जंप करण्यापूर्वी स्वच्छ करा आणि घट्ट करा.', 'ટર્મિનલ પર સફેદ/લીલો પાવડર? જમ્પ કરતા પહેલા સાફ કરી કસો.', 'ಟರ್ಮಿನಲ್‌ಗಳ ಮೇಲೆ ಬಿಳಿ/ಹಸಿರು ಪುಡಿ? ಜಂಪ್ ಮಾಡುವ ಮೊದಲು ಸ್ವಚ್ಛಗೊಳಿಸಿ ಬಿಗಿಗೊಳಿಸಿ.', 'ടെർമിനലുകളിൽ വെള്ള/പച്ച പൊടി? ജംപ് ചെയ്യുന്നതിന് മുമ്പ് വൃത്തിയാക്കി മുറുക്കുക.'),
          steps: [ m('Open the bonnet, find the battery.', 'बोनट खोलें, बैटरी ढूँढें।', 'பானட்டை திறந்து, பேட்டரியை கண்டுபிடியுங்கள்.', 'బానెట్ తెరిచి, బ్యాటరీని కనుగొనండి.', 'বনেট খুলুন, ব্যাটারি খুঁজুন।', 'बॉनेट उघडा, बॅटरी शोधा.', 'બોનેટ ખોલો, બેટરી શોધો.', 'ಬೋನೆಟ್ ತೆರೆಯಿರಿ, ಬ್ಯಾಟರಿ ಹುಡುಕಿ.', 'ബോണറ്റ് തുറന്ന്, ബാറ്ററി കണ്ടെത്തുക.'), m('Tighten both terminal clamps; wipe off corrosion with a cloth.', 'दोनों टर्मिनल क्लैंप कसें; जंग कपड़े से पोंछें।', 'இரண்டு டெர்மினல் கிளாம்புகளையும் இறுக்குங்கள்; துருவை துணியால் துடைக்கவும்.', 'రెండు టర్మినల్ క్లాంప్‌లను బిగించండి; తుప్పును గుడ్డతో తుడవండి.', 'দুটি টার্মিনাল ক্ল্যাম্প শক্ত করুন; মরিচা কাপড় দিয়ে মুছুন।', 'दोन्ही टर्मिनल क्लॅम्प घट्ट करा; गंज कापडाने पुसा.', 'બંને ટર્મિનલ ક્લેમ્પ કસો; કાટ કપડાથી લૂછો.', 'ಎರಡೂ ಟರ್ಮಿನಲ್ ಕ್ಲಾಂಪ್ ಬಿಗಿಗೊಳಿಸಿ; ತುಕ್ಕನ್ನು ಬಟ್ಟೆಯಿಂದ ಒರೆಸಿ.', 'രണ്ട് ടെർമിനൽ ക്ലാമ്പുകളും മുറുക്കുക; തുരുമ്പ് തുണി കൊണ്ട് തുടയ്ക്കുക.'), m('Try starting again.', 'फिर स्टार्ट करें।', 'மீண்டும் ஸ்டார்ட் செய்யுங்கள்.', 'మళ్లీ స్టార్ట్ చేయండి.', 'আবার স্টার্ট করুন।', 'पुन्हा सुरू करा.', 'ફરી સ્ટાર્ટ કરો.', 'ಮತ್ತೆ ಸ್ಟಾರ್ಟ್ ಮಾಡಿ.', 'വീണ്ടും സ്റ്റാർട്ട് ചെയ്യുക.') ],
          ifFails: m('Clean terminals but still dead → jump start (above) or tow.', 'टर्मिनल साफ़ पर बंद → जंप स्टार्ट (ऊपर) या टो।', 'டெர்மினல்கள் சுத்தமாக இருந்தும் வேலை செய்யவில்லையா → ஜம்ப் ஸ்டார்ட் (மேலே) அல்லது டோ.', 'టర్మినల్స్ శుభ్రంగా ఉన్నా పని చేయలేదా → జంప్ స్టార్ట్ (పైన) లేదా టో.', 'টার্মিনাল পরিষ্কার তবু বন্ধ → জাম্প স্টার্ট (উপরে) বা টো।', 'टर्मिनल स्वच्छ तरी बंद → जंप स्टार्ट (वर) किंवा टो.', 'ટર્મિનલ સાફ છતાં બંધ → જમ્પ સ્ટાર્ટ (ઉપર) કે ટો.', 'ಟರ್ಮಿನಲ್ ಸ್ವಚ್ಛ ಆದರೂ ಬಂದ್ → ಜಂಪ್ ಸ್ಟಾರ್ಟ್ (ಮೇಲೆ) ಅಥವಾ ಟೋ.', 'ടെർമിനലുകൾ വൃത്തിയായിട്ടും ഓഫ് → ജംപ് സ്റ്റാർട്ട് (മുകളിൽ) അല്ലെങ്കിൽ ടോ.'), mechCost: '₹0–₹300' }
      ],
      towMsg: m('No crank after a jump → starter motor or ignition. SOS family, and tell the shop "no-crank, battery & terminals checked" to avoid an upsell.', 'जंप के बाद भी क्रैंक नहीं → स्टार्टर मोटर या इग्निशन। SOS करें, और दुकान को कहें "no-crank, battery & terminals checked"।', 'ஜம்ப் செய்த பிறகும் க்ரேங்க் இல்லையா → ஸ்டார்ட்டர் மோட்டார் அல்லது இக்னிஷன். குடும்பத்திற்கு SOS செய்யுங்கள், கடையில் "no-crank, battery & terminals checked" என்று சொல்லுங்கள், அதிக கட்டணம் தவிர்க்க.', 'జంప్ చేసినా క్రాంక్ లేదా → స్టార్టర్ మోటార్ లేదా ఇగ్నిషన్. కుటుంబానికి SOS చేయండి, షాప్‌లో "no-crank, battery & terminals checked" అని చెప్పండి, ఎక్కువ ధర తప్పించుకోవడానికి.', 'জাম্পের পরও ক্র্যাঙ্ক নেই → স্টার্টার মোটর বা ইগনিশন। পরিবারকে SOS করুন, এবং দোকানে বলুন "no-crank, battery & terminals checked" যাতে বেশি দাম এড়ানো যায়।', 'जंप केल्यावरही क्रँक नाही → स्टार्टर मोटर किंवा इग्निशन. कुटुंबाला SOS करा, आणि दुकानात सांगा "no-crank, battery & terminals checked" म्हणजे जास्त किंमत टाळता येईल.', 'જમ્પ પછી પણ ક્રેન્ક નહીં → સ્ટાર્ટર મોટર કે ઇગ્નિશન. પરિવારને SOS કરો, અને દુકાનમાં કહો "no-crank, battery & terminals checked" જેથી વધારે ભાવ ટળે.', 'ಜಂಪ್ ಮಾಡಿದರೂ ಕ್ರ್ಯಾಂಕ್ ಇಲ್ಲ → ಸ್ಟಾರ್ಟರ್ ಮೋಟಾರ್ ಅಥವಾ ಇಗ್ನಿಷನ್. ಕುಟುಂಬಕ್ಕೆ SOS ಮಾಡಿ, ಮತ್ತು ಅಂಗಡಿಯಲ್ಲಿ "no-crank, battery & terminals checked" ಎಂದು ಹೇಳಿ, ಹೆಚ್ಚಿನ ದರ ತಪ್ಪಿಸಲು.', 'ജംപ് ചെയ്തിട്ടും ക്രാങ്ക് ഇല്ല → സ്റ്റാർട്ടർ മോട്ടോർ അല്ലെങ്കിൽ ഇഗ്നിഷൻ. കുടുംബത്തിന് SOS ചെയ്യുക, കടയിൽ "no-crank, battery & terminals checked" എന്ന് പറയുക, അമിത വില ഒഴിവാക്കാൻ.')
    },
    {
      id: 'car_overheat', v: '4w', icon: '🌡️',
      name: m('Overheating — temp red / steam', 'ज़्यादा गरम — टेम्परेचर रेड / भाप', 'அதிக வெப்பம் — டெம்ப் சிவப்பு / நீராவி', 'మరీ వేడెక్కడం — టెంప్ ఎరుపు / ఆవిరి', 'অতিরিক্ত গরম — টেম্প লাল / বাষ্প', 'जास्त गरम — टेंप लाल / वाफ', 'વધુ ગરમ — ટેમ્પ લાલ / વરાળ', 'ಅತಿಯಾಗಿ ಬಿಸಿ — ಟೆಂಪ್ ಕೆಂಪು / ಹಬೆ', 'അമിത ചൂട് — ടെംപ് ചുവപ്പ് / ആവി'),
      safety: { red: true, warn: m('🔴 STOP NOW. Steam or a red temp gauge means STOP and switch off — driving on warps the head, a ₹50,000+ repair. Never open the radiator hot.', '🔴 अभी रोकें। भाप या रेड टेम्प = रोकें और बंद करें — चलाते रहना सिर पर असर, ₹50,000+ मरम्मत। गरम रेडिएटर कभी न खोलें।', '🔴 இப்போதே நிறுத்துங்கள். நீராவி அல்லது சிவப்பு டெம்ப் கேஜ் = நிறுத்தி ஆஃப் செய்யுங்கள் — தொடர்ந்து ஓட்டினால் ஹெட் வளையும், ₹50,000+ பழுது. சூடான ரேடியேட்டரை ஒருபோதும் திறக்காதீர்கள்.', '🔴 ఇప్పుడే ఆపండి. ఆవిరి లేదా ఎరుపు టెంప్ గేజ్ = ఆపి ఆఫ్ చేయండి — నడుపుతూ ఉంటే హెడ్ వంగుతుంది, ₹50,000+ మరమ్మతు. వేడి రేడియేటర్‌ను ఎప్పుడూ తెరవకండి.', '🔴 এখনই থামুন। বাষ্প বা লাল টেম্প গেজ = থামুন ও বন্ধ করুন — চালিয়ে গেলে হেড বেঁকে যায়, ₹50,000+ মেরামত। গরম রেডিয়েটর কখনও খুলবেন না।', '🔴 आताच थांबा. वाफ किंवा लाल टेंप गेज = थांबा आणि बंद करा — चालवत राहिल्यास हेड वाकतो, ₹50,000+ दुरुस्ती. गरम रेडिएटर कधीही उघडू नका.', '🔴 હમણાં જ રોકો. વરાળ કે લાલ ટેમ્પ ગેજ = રોકો અને બંધ કરો — ચલાવતા રહેવાથી હેડ વાંકો થાય, ₹50,000+ રિપેર. ગરમ રેડિએટર ક્યારેય ન ખોલો.', '🔴 ಈಗಲೇ ನಿಲ್ಲಿಸಿ. ಹಬೆ ಅಥವಾ ಕೆಂಪು ಟೆಂಪ್ ಗೇಜ್ = ನಿಲ್ಲಿಸಿ ಆಫ್ ಮಾಡಿ — ಓಡಿಸುತ್ತಿದ್ದರೆ ಹೆಡ್ ಬಾಗುತ್ತದೆ, ₹50,000+ ದುರಸ್ತಿ. ಬಿಸಿ ರೇಡಿಯೇಟರ್ ಅನ್ನು ಎಂದಿಗೂ ತೆರೆಯಬೇಡಿ.', '🔴 ഇപ്പോൾ തന്നെ നിർത്തുക. ആവി അല്ലെങ്കിൽ ചുവന്ന ടെംപ് ഗേജ് = നിർത്തി ഓഫ് ചെയ്യുക — ഓടിച്ചാൽ ഹെഡ് വളയും, ₹50,000+ റിപ്പയർ. ചൂടുള്ള റേഡിയേറ്റർ ഒരിക്കലും തുറക്കരുത്.') },
      causes: [
        { name: m('Engine overheating', 'इंजन ज़्यादा गरम', 'இன்ஜின் அதிக வெப்பம்', 'ఇంజిన్ మరీ వేడెక్కడం', 'ইঞ্জিন অতিরিক্ত গরম', 'इंजिन जास्त गरम', 'એન્જિન વધુ ગરમ', 'ಇಂಜಿನ್ ಅತಿಯಾಗಿ ಬಿಸಿ', 'എഞ്ചിൻ അമിത ചൂട്'), pct: 100, tier: 'red', diff: 9, timeMin: 30,
          tools: m('Coolant / water — ONLY after fully cool', 'कूलेंट / पानी — सिर्फ़ पूरा ठंडा होने पर', 'கூலன்ட் / தண்ணீர் — முழுவதும் குளிர்ந்த பிறகு மட்டுமே', 'కూలెంట్ / నీరు — పూర్తిగా చల్లబడ్డాకే', 'কুল্যান্ট / পানি — শুধু পুরোপুরি ঠান্ডা হলে', 'कूलंट / पाणी — फक्त पूर्ण थंड झाल्यावर', 'કૂલન્ટ / પાણી — માત્ર પૂરા ઠંડા થયા પછી', 'ಕೂಲೆಂಟ್ / ನೀರು — ಪೂರ್ತಿ ತಣ್ಣಗಾದ ನಂತರ ಮಾತ್ರ', 'കൂളന്റ് / വെള്ളം — പൂർണമായി തണുത്ത ശേഷം മാത്രം'),
          check: m('Temp needle in the red or steam from the bonnet? This is a stop-now situation.', 'टेम्प सुई रेड में या बोनट से भाप? यह अभी-रोको स्थिति है।', 'டெம்ப் ஊசி சிவப்பில் அல்லது பானட்டிலிருந்து நீராவியா? இது இப்போதே-நிறுத்து நிலை.', 'టెంప్ సూది ఎరుపులో లేదా బానెట్ నుండి ఆవిరా? ఇది ఇప్పుడే-ఆపు పరిస్థితి.', 'টেম্প সূচ লালে বা বনেট থেকে বাষ্প? এটা এখনই-থামার পরিস্থিতি।', 'टेंप सुई लालमध्ये किंवा बॉनेटमधून वाफ? ही आताच-थांबा स्थिती.', 'ટેમ્પ સોય લાલમાં કે બોનેટમાંથી વરાળ? આ હમણાં-રોકો સ્થિતિ છે.', 'ಟೆಂಪ್ ಸೂಜಿ ಕೆಂಪಿನಲ್ಲಿ ಅಥವಾ ಬೋನೆಟ್‌ನಿಂದ ಹಬೆ? ಇದು ಈಗಲೇ-ನಿಲ್ಲಿಸು ಸ್ಥಿತಿ.', 'ടെംപ് സൂചി ചുവപ്പിൽ അല്ലെങ്കിൽ ബോണറ്റിൽ നിന്ന് ആവി? ഇത് ഇപ്പോൾ-നിർത്തുക സാഹചര്യം.'),
          steps: [ m('Pull over safely, hazards on, switch the engine OFF.', 'सुरक्षित रोकें, हज़ार्ड ऑन, इंजन बंद करें।', 'பாதுகாப்பாக நிறுத்தி, ஹேசர்ட் ஆன், இன்ஜினை OFF செய்யுங்கள்.', 'సురక్షితంగా ఆపి, హజార్డ్ ఆన్, ఇంజిన్‌ను OFF చేయండి.', 'নিরাপদে থামুন, হ্যাজার্ড অন, ইঞ্জিন OFF করুন।', 'सुरक्षित थांबा, हजार्ड ऑन, इंजिन OFF करा.', 'સલામત રીતે રોકો, હેઝાર્ડ ઓન, એન્જિન OFF કરો.', 'ಸುರಕ್ಷಿತವಾಗಿ ನಿಲ್ಲಿಸಿ, ಹಜಾರ್ಡ್ ಆನ್, ಇಂಜಿನ್ OFF ಮಾಡಿ.', 'സുരക്ഷിതമായി നിർത്തുക, ഹസാർഡ് ഓൺ, എഞ്ചിൻ OFF ചെയ്യുക.'), m('Open the bonnet from outside to release heat. Do NOT touch the radiator cap.', 'बाहर से बोनट खोलें ताकि गरमी निकले। रेडिएटर कैप न छुएँ।', 'வெப்பம் வெளியேற பானட்டை வெளியிலிருந்து திறங்கள். ரேடியேட்டர் கேப்பை தொடாதீர்கள்.', 'వేడి బయటకు పోవడానికి బానెట్‌ను బయటి నుండి తెరవండి. రేడియేటర్ క్యాప్‌ను తాకవద్దు.', 'তাপ বের হতে বনেট বাইরে থেকে খুলুন। রেডিয়েটর ক্যাপ ছোঁবেন না।', 'उष्णता बाहेर पडण्यासाठी बॉनेट बाहेरून उघडा. रेडिएटर कॅपला स्पर्श करू नका.', 'ગરમી નીકળવા બોનેટ બહારથી ખોલો. રેડિએટર કેપને સ્પર્શ ન કરો.', 'ಶಾಖ ಹೊರಬರಲು ಬೋನೆಟ್ ಅನ್ನು ಹೊರಗಿನಿಂದ ತೆರೆಯಿರಿ. ರೇಡಿಯೇಟರ್ ಕ್ಯಾಪ್ ಮುಟ್ಟಬೇಡಿ.', 'ചൂട് പുറത്തുവിടാൻ ബോണറ്റ് പുറത്തുനിന്ന് തുറക്കുക. റേഡിയേറ്റർ ക്യാപ് തൊടരുത്.'), m('Wait at least 30 minutes until fully cool.', 'कम से कम 30 मिनट रुकें जब तक पूरा ठंडा न हो।', 'முழுவதும் குளிரும் வரை குறைந்தது 30 நிமிடம் காத்திருங்கள்.', 'పూర్తిగా చల్లబడే వరకు కనీసం 30 నిమిషాలు వేచి ఉండండి.', 'পুরোপুরি ঠান্ডা না হওয়া পর্যন্ত অন্তত 30 মিনিট অপেক্ষা করুন।', 'पूर्ण थंड होईपर्यंत किमान 30 मिनिटे थांबा.', 'પૂરા ઠંડા થાય ત્યાં સુધી ઓછામાં ઓછી 30 મિનિટ રાહ જુઓ.', 'ಪೂರ್ತಿ ತಣ್ಣಗಾಗುವವರೆಗೆ ಕನಿಷ್ಠ 30 ನಿಮಿಷ ಕಾಯಿರಿ.', 'പൂർണമായി തണുക്കുന്നതുവരെ കുറഞ്ഞത് 30 മിനിറ്റ് കാത്തിരിക്കുക.'), m('Only when cool: top up the coolant reservoir, then drive gently to a shop.', 'सिर्फ़ ठंडा होने पर: कूलेंट रिज़र्वायर भरें, फिर धीरे दुकान तक जाएँ।', 'குளிர்ந்த பிறகு மட்டுமே: கூலன்ட் ரிசர்வாயரை நிரப்பி, பிறகு மெதுவாக கடைக்கு செல்லுங்கள்.', 'చల్లబడ్డాకే: కూలెంట్ రిజర్వాయర్‌ను నింపి, తర్వాత మెల్లగా షాప్‌కు నడపండి.', 'শুধু ঠান্ডা হলে: কুল্যান্ট রিজার্ভয়ার ভরুন, তারপর আস্তে দোকানে যান।', 'फक्त थंड झाल्यावर: कूलंट रिझर्व्हायर भरा, मग हळू दुकानात जा.', 'માત્ર ઠંડું થાય ત્યારે: કૂલન્ટ રિઝર્વોયર ભરો, પછી ધીમે દુકાને જાઓ.', 'ತಣ್ಣಗಾದ ನಂತರ ಮಾತ್ರ: ಕೂಲೆಂಟ್ ರಿಸರ್ವಾಯರ್ ತುಂಬಿಸಿ, ನಂತರ ಮೆಲ್ಲಗೆ ಅಂಗಡಿಗೆ ಓಡಿಸಿ.', 'തണുത്ത ശേഷം മാത്രം: കൂളന്റ് റിസർവോയർ നിറയ്ക്കുക, പിന്നെ പതുക്കെ കടയിലേക്ക് ഓടിക്കുക.') ],
          ifFails: m('Coolant pours out underneath / overheats in minutes → tow, do not drive.', 'कूलेंट नीचे बहे / मिनटों में गरम → टो करें, न चलाएँ।', 'கூலன்ட் கீழே வழிகிறது / நிமிடங்களில் சூடாகிறதா → டோ செய்யுங்கள், ஓட்டாதீர்கள்.', 'కూలెంట్ కింద కారుతోంది / నిమిషాల్లో వేడెక్కుతోందా → టో చేయండి, నడపవద్దు.', 'কুল্যান্ট নিচে বেরোচ্ছে / মিনিটে গরম → টো করুন, চালাবেন না।', 'कूलंट खाली वाहते / मिनिटांत गरम → टो करा, चालवू नका.', 'કૂલન્ટ નીચે વહે / મિનિટોમાં ગરમ → ટો કરો, ન ચલાવો.', 'ಕೂಲೆಂಟ್ ಕೆಳಗೆ ಹರಿಯುತ್ತದೆ / ನಿಮಿಷಗಳಲ್ಲಿ ಬಿಸಿಯಾಗುತ್ತದೆ → ಟೋ ಮಾಡಿ, ಓಡಿಸಬೇಡಿ.', 'കൂളന്റ് താഴെ ഒഴുകുന്നു / മിനിറ്റുകൾക്കുള്ളിൽ ചൂടാകുന്നു → ടോ ചെയ്യുക, ഓടിക്കരുത്.'), mechCost: '₹500–₹50,000' }
      ],
      towMsg: m('🔴 If it overheats again within minutes, a hose or pump has failed — TOW it. Driving an overheating engine is the single most expensive mistake an owner makes.', '🔴 मिनटों में फिर गरम हो तो होज़ या पंप फेल — टो करें। गरम इंजन चलाना मालिक की सबसे महँगी गलती है।', '🔴 நிமிடங்களில் மீண்டும் சூடானால் ஹோஸ் அல்லது பம்ப் செயலிழந்துள்ளது — டோ செய்யுங்கள். அதிக வெப்பமான இன்ஜினை ஓட்டுவது உரிமையாளர் செய்யும் மிக விலையுயர்ந்த தவறு.', '🔴 నిమిషాల్లో మళ్లీ వేడెక్కితే హోస్ లేదా పంప్ విఫలమైంది — టో చేయండి. వేడెక్కిన ఇంజిన్‌ను నడపడం యజమాని చేసే అత్యంత ఖరీదైన తప్పు.', '🔴 মিনিটে আবার গরম হলে হোস বা পাম্প ফেল করেছে — টো করুন। গরম ইঞ্জিন চালানো মালিকের সবচেয়ে দামি ভুল।', '🔴 मिनिटांत पुन्हा गरम झाल्यास होज किंवा पंप फेल झाला आहे — टो करा. गरम इंजिन चालवणे मालकाची सर्वात महाग चूक आहे.', '🔴 મિનિટોમાં ફરી ગરમ થાય તો હોઝ કે પંપ ફેલ થયો છે — ટો કરો. ગરમ એન્જિન ચલાવવું માલિકની સૌથી મોંઘી ભૂલ છે.', '🔴 ನಿಮಿಷಗಳಲ್ಲಿ ಮತ್ತೆ ಬಿಸಿಯಾದರೆ ಹೋಸ್ ಅಥವಾ ಪಂಪ್ ವಿಫಲವಾಗಿದೆ — ಟೋ ಮಾಡಿ. ಬಿಸಿಯಾದ ಇಂಜಿನ್ ಓಡಿಸುವುದು ಮಾಲೀಕ ಮಾಡುವ ಅತ್ಯಂತ ದುಬಾರಿ ತಪ್ಪು.', '🔴 മിനിറ്റുകൾക്കുള്ളിൽ വീണ്ടും ചൂടായാൽ ഹോസ് അല്ലെങ്കിൽ പമ്പ് പരാജയപ്പെട്ടു — ടോ ചെയ്യുക. ചൂടായ എഞ്ചിൻ ഓടിക്കുന്നത് ഉടമ ചെയ്യുന്ന ഏറ്റവും ചെലവേറിയ തെറ്റാണ്.')
    },
    {
      id: 'car_flat_tyre', v: '4w', icon: '🛞',
      name: m('Flat tyre — change the stepney', 'टायर पंक्चर — स्टेपनी बदलें', 'டயர் பஞ்சர் — ஸ்டெப்னி மாற்றுங்கள்', 'టైర్ పంక్చర్ — స్టెప్నీ మార్చండి', 'টায়ার পাংচার — স্টেপনি বদলান', 'टायर पंक्चर — स्टेपनी बदला', 'ટાયર પંક્ચર — સ્ટેપની બદલો', 'ಟೈರ್ ಪಂಕ್ಚರ್ — ಸ್ಟೆಪ್ನಿ ಬದಲಿಸಿ', 'ടയർ പഞ്ചർ — സ്റ്റെപ്നി മാറ്റുക'),
      safety: { red: false, warn: m('Stop on flat, firm ground away from traffic. Hazards on. Never get under a car on a jack.', 'समतल, ठोस ज़मीन पर ट्रैफ़िक से दूर रोकें। हज़ार्ड ऑन। जैक पर चढ़ी कार के नीचे कभी न जाएँ।', 'டிராஃபிக்கிலிருந்து விலகி, சமமான, உறுதியான தரையில் நிறுத்துங்கள். ஹேசர்ட் ஆன். ஜாக்கில் ஏற்றிய காரின் கீழே ஒருபோதும் செல்லாதீர்கள்.', 'ట్రాఫిక్ నుండి దూరంగా, చదునైన, గట్టి నేలపై ఆపండి. హజార్డ్ ఆన్. జాక్‌పై ఉన్న కారు కింద ఎప్పుడూ వెళ్లవద్దు.', 'ট্রাফিক থেকে দূরে, সমতল, শক্ত মাটিতে থামুন। হ্যাজার্ড অন। জ্যাকে তোলা গাড়ির নিচে কখনও যাবেন না।', 'ट्रॅफिकपासून दूर, सपाट, घट्ट जमिनीवर थांबा. हजार्ड ऑन. जॅकवर चढवलेल्या कारखाली कधीही जाऊ नका.', 'ટ્રાફિકથી દૂર, સમતળ, મજબૂત જમીન પર રોકો. હેઝાર્ડ ઓન. જેક પર ચઢાવેલી કાર નીચે ક્યારેય ન જાઓ.', 'ಟ್ರಾಫಿಕ್‌ನಿಂದ ದೂರ, ಸಮತಟ್ಟಾದ, ಗಟ್ಟಿ ನೆಲದಲ್ಲಿ ನಿಲ್ಲಿಸಿ. ಹಜಾರ್ಡ್ ಆನ್. ಜ್ಯಾಕ್ ಮೇಲಿನ ಕಾರಿನ ಕೆಳಗೆ ಎಂದಿಗೂ ಹೋಗಬೇಡಿ.', 'ട്രാഫിക്കിൽ നിന്ന് മാറി, പരന്ന, ഉറപ്പുള്ള നിലത്ത് നിർത്തുക. ഹസാർഡ് ഓൺ. ജാക്കിൽ കയറ്റിയ കാറിന് താഴെ ഒരിക്കലും കയറരുത്.') },
      causes: [
        { name: m('Change to the spare (stepney)', 'स्टेपनी (स्पेयर) लगाएँ', 'ஸ்டெப்னி (ஸ்பேர்) போடுங்கள்', 'స్టెప్నీ (స్పేర్) వేయండి', 'স্টেপনি (স্পেয়ার) লাগান', 'स्टेपनी (स्पेअर) लावा', 'સ્ટેપની (સ્પેર) લગાવો', 'ಸ್ಟೆಪ್ನಿ (ಸ್ಪೇರ್) ಹಾಕಿ', 'സ്റ്റെപ്നി (സ്പെയർ) ഇടുക'), pct: 100, tier: 'amber', diff: 5, timeMin: 25,
          tools: m('Jack, wheel spanner, spare — all in the boot', 'जैक, व्हील स्पैनर, स्पेयर — सब डिक्की में', 'ஜாக், வீல் ஸ்பேனர், ஸ்பேர் — அனைத்தும் டிக்கியில்', 'జాక్, వీల్ స్పానర్, స్పేర్ — అన్నీ డిక్కీలో', 'জ্যাক, হুইল স্প্যানার, স্পেয়ার — সব ডিকিতে', 'जॅक, व्हील स्पॅनर, स्पेअर — सर्व डिकीमध्ये', 'જેક, વ્હીલ સ્પેનર, સ્પેર — બધું ડિકીમાં', 'ಜ್ಯಾಕ್, ವೀಲ್ ಸ್ಪ್ಯಾನರ್, ಸ್ಪೇರ್ — ಎಲ್ಲವೂ ಡಿಕ್ಕಿಯಲ್ಲಿ', 'ജാക്ക്, വീൽ സ്പാനർ, സ്പെയർ — എല്ലാം ഡിക്കിയിൽ'),
          check: m('Do you have the spare, jack and spanner from the boot? Park brake on, hazards on.', 'डिक्की में स्पेयर, जैक और स्पैनर है? पार्क ब्रेक ऑन, हज़ार्ड ऑन।', 'டிக்கியில் ஸ்பேர், ஜாக், ஸ்பேனர் உள்ளதா? பார்க் பிரேக் ஆன், ஹேசர்ட் ஆன்.', 'డిక్కీలో స్పేర్, జాక్, స్పానర్ ఉన్నాయా? పార్క్ బ్రేక్ ఆన్, హజార్డ్ ఆన్.', 'ডিকিতে স্পেয়ার, জ্যাক ও স্প্যানার আছে? পার্ক ব্রেক অন, হ্যাজার্ড অন।', 'डिकीमध्ये स्पेअर, जॅक आणि स्पॅनर आहे? पार्क ब्रेक ऑन, हजार्ड ऑन.', 'ડિકીમાં સ્પેર, જેક અને સ્પેનર છે? પાર્ક બ્રેક ઓન, હેઝાર્ડ ઓન.', 'ಡಿಕ್ಕಿಯಲ್ಲಿ ಸ್ಪೇರ್, ಜ್ಯಾಕ್ ಮತ್ತು ಸ್ಪ್ಯಾನರ್ ಇದೆಯೇ? ಪಾರ್ಕ್ ಬ್ರೇಕ್ ಆನ್, ಹಜಾರ್ಡ್ ಆನ್.', 'ഡിക്കിയിൽ സ്പെയർ, ജാക്ക്, സ്പാനർ ഉണ്ടോ? പാർക്ക് ബ്രേക്ക് ഓൺ, ഹസാർഡ് ഓൺ.'),
          steps: [ m('Loosen each wheel nut half a turn WHILE the tyre is still on the ground.', 'टायर ज़मीन पर रहते हुए हर नट आधा घुमाव ढीला करें।', 'டயர் தரையில் இருக்கும்போதே ஒவ்வொரு வீல் நட்டையும் அரை சுற்று தளர்த்துங்கள்.', 'టైర్ నేలపై ఉన్నప్పుడే ప్రతి వీల్ నట్‌ను సగం తిప్పు వదులు చేయండి.', 'টায়ার মাটিতে থাকা অবস্থায় প্রতিটি হুইল নাট আধা প্যাঁচ ঢিলে করুন।', 'टायर जमिनीवर असतानाच प्रत्येक व्हील नट अर्धा फेरा सैल करा.', 'ટાયર જમીન પર હોય ત્યારે જ દરેક વ્હીલ નટ અડધો વળાંક ઢીલો કરો.', 'ಟೈರ್ ನೆಲದಲ್ಲಿರುವಾಗಲೇ ಪ್ರತಿ ವೀಲ್ ನಟ್ ಅನ್ನು ಅರ್ಧ ತಿರುವು ಸಡಿಲಗೊಳಿಸಿ.', 'ടയർ നിലത്തായിരിക്കുമ്പോൾ തന്നെ ഓരോ വീൽ നട്ടും അര തിരിവ് അയയ്ക്കുക.'), m('Place the jack at the marked jacking point nearest the flat; raise until the tyre is just off the ground.', 'पंक्चर के पास निशान वाले जैकिंग पॉइंट पर जैक लगाएँ; टायर ज़मीन से थोड़ा ऊपर तक उठाएँ।', 'பஞ்சருக்கு அருகிலுள்ள குறிக்கப்பட்ட ஜாக்கிங் பாயிண்டில் ஜாக் வைக்கவும்; டயர் தரையிலிருந்து சற்று மேலே வரும் வரை உயர்த்துங்கள்.', 'పంక్చర్‌కు దగ్గరి గుర్తు పెట్టిన జాకింగ్ పాయింట్‌లో జాక్ ఉంచండి; టైర్ నేల నుండి కొద్దిగా పైకి వచ్చే వరకు ఎత్తండి.', 'পাংচারের কাছের চিহ্নিত জ্যাকিং পয়েন্টে জ্যাক রাখুন; টায়ার মাটি থেকে একটু উপরে ওঠা পর্যন্ত তুলুন।', 'पंक्चरजवळच्या खुणा केलेल्या जॅकिंग पॉइंटवर जॅक ठेवा; टायर जमिनीपासून किंचित वर येईपर्यंत उचला.', 'પંક્ચર પાસેના નિશાનવાળા જેકિંગ પોઇન્ટ પર જેક મૂકો; ટાયર જમીનથી થોડું ઉપર આવે ત્યાં સુધી ઉઠાવો.', 'ಪಂಕ್ಚರ್ ಬಳಿಯ ಗುರುತಿನ ಜಾಕಿಂಗ್ ಪಾಯಿಂಟ್‌ನಲ್ಲಿ ಜ್ಯಾಕ್ ಇಡಿ; ಟೈರ್ ನೆಲದಿಂದ ಸ್ವಲ್ಪ ಮೇಲೆ ಬರುವವರೆಗೆ ಎತ್ತಿ.', 'പഞ്ചറിന് അടുത്തുള്ള അടയാളപ്പെടുത്തിയ ജാക്കിംഗ് പോയിന്റിൽ ജാക്ക് വയ്ക്കുക; ടയർ നിലത്തുനിന്ന് അൽപം ഉയരുന്നതുവരെ ഉയർത്തുക.'), m('Remove the nuts, swap the flat for the spare, hand-tighten the nuts.', 'नट निकालें, पंक्चर की जगह स्पेयर लगाएँ, हाथ से नट कसें।', 'நட்களை கழற்றி, பஞ்சர் டயருக்கு பதிலாக ஸ்பேரை மாற்றி, கையால் நட்களை இறுக்குங்கள்.', 'నట్‌లను తీసి, పంక్చర్ స్థానంలో స్పేర్ వేసి, చేతితో నట్‌లను బిగించండి.', 'নাট খুলুন, পাংচারের জায়গায় স্পেয়ার লাগান, হাতে নাট শক্ত করুন।', 'नट काढा, पंक्चरच्या जागी स्पेअर लावा, हाताने नट घट्ट करा.', 'નટ કાઢો, પંક્ચરની જગ્યાએ સ્પેર લગાવો, હાથે નટ કસો.', 'ನಟ್‌ಗಳನ್ನು ತೆಗೆದು, ಪಂಕ್ಚರ್ ಬದಲು ಸ್ಪೇರ್ ಹಾಕಿ, ಕೈಯಿಂದ ನಟ್ ಬಿಗಿಗೊಳಿಸಿ.', 'നട്ടുകൾ ഊരി, പഞ്ചറിന് പകരം സ്പെയർ വച്ച്, കൈകൊണ്ട് നട്ടുകൾ മുറുക്കുക.'), m('Lower the car, then fully tighten the nuts in a star/cross pattern.', 'कार नीचे करें, फिर नट को क्रॉस/स्टार क्रम में पूरा कसें।', 'காரை இறக்கி, பிறகு நட்களை ஸ்டார்/கிராஸ் முறையில் முழுவதும் இறுக்குங்கள்.', 'కారును కిందికి దించి, తర్వాత నట్‌లను స్టార్/క్రాస్ క్రమంలో పూర్తిగా బిగించండి.', 'গাড়ি নামান, তারপর নাটগুলো স্টার/ক্রস প্যাটার্নে পুরো শক্ত করুন।', 'कार खाली करा, मग नट स्टार/क्रॉस क्रमाने पूर्ण घट्ट करा.', 'કાર નીચે કરો, પછી નટને સ્ટાર/ક્રોસ ક્રમમાં પૂરા કસો.', 'ಕಾರನ್ನು ಕೆಳಗಿಳಿಸಿ, ನಂತರ ನಟ್‌ಗಳನ್ನು ಸ್ಟಾರ್/ಕ್ರಾಸ್ ಕ್ರಮದಲ್ಲಿ ಪೂರ್ತಿ ಬಿಗಿಗೊಳಿಸಿ.', 'കാർ താഴ്ത്തി, പിന്നെ നട്ടുകൾ സ്റ്റാർ/ക്രോസ് ക്രമത്തിൽ പൂർണമായി മുറുക്കുക.') ],
          ifFails: m('No spare or no jacking point you trust → SOS / call roadside, don\'t improvise a jack.', 'स्पेयर नहीं या भरोसेमंद जैकिंग पॉइंट नहीं → SOS / रोडसाइड बुलाएँ, जैक न जुगाड़ें।', 'ஸ்பேர் இல்லை அல்லது நம்பகமான ஜாக்கிங் பாயிண்ட் இல்லையா → SOS / ரோடுசைடு அழைக்கவும், ஜாக்கை ஜுகாட் செய்யாதீர்கள்.', 'స్పేర్ లేదు లేదా నమ్మదగిన జాకింగ్ పాయింట్ లేదా → SOS / రోడ్‌సైడ్ పిలవండి, జాక్‌ను తాత్కాలికంగా చేయవద్దు.', 'স্পেয়ার নেই বা বিশ্বস্ত জ্যাকিং পয়েন্ট নেই → SOS / রোডসাইড ডাকুন, জ্যাক জোড়াতালি দেবেন না।', 'स्पेअर नाही किंवा विश्वासार्ह जॅकिंग पॉइंट नाही → SOS / रोडसाईड बोलवा, जॅक जुगाड करू नका.', 'સ્પેર નથી કે ભરોસાપાત્ર જેકિંગ પોઇન્ટ નથી → SOS / રોડસાઇડ બોલાવો, જેક જુગાડ ન કરો.', 'ಸ್ಪೇರ್ ಇಲ್ಲ ಅಥವಾ ನಂಬಬಹುದಾದ ಜಾಕಿಂಗ್ ಪಾಯಿಂಟ್ ಇಲ್ಲ → SOS / ರೋಡ್‌ಸೈಡ್ ಕರೆಯಿರಿ, ಜ್ಯಾಕ್ ಜುಗಾಡ್ ಮಾಡಬೇಡಿ.', 'സ്പെയർ ഇല്ല അല്ലെങ്കിൽ വിശ്വസിക്കാവുന്ന ജാക്കിംഗ് പോയിന്റ് ഇല്ല → SOS / റോഡ്‌സൈഡ് വിളിക്കുക, ജാക്ക് താൽക്കാലികമായി ഉണ്ടാക്കരുത്.'), mechCost: '₹0 (DIY) / ₹100–₹300 (help)' }
      ],
      towMsg: m('Spare fitted but it\'s a thin space-saver? Drive under 80 km/h straight to a tyre shop. Get the puncture fixed the same day.', 'पतली स्पेस-सेवर स्पेयर लगी? 80 km/h से कम पर सीधे टायर दुकान जाएँ। उसी दिन पंक्चर ठीक कराएँ।', 'மெல்லிய ஸ்பேஸ்-சேவர் ஸ்பேர் போடப்பட்டதா? 80 km/h க்கு கீழே நேராக டயர் கடைக்கு செல்லுங்கள். அதே நாளில் பஞ்சரை சரிசெய்யுங்கள்.', 'సన్నని స్పేస్-సేవర్ స్పేర్ వేశారా? 80 km/h లోపు నేరుగా టైర్ షాప్‌కు నడపండి. అదే రోజు పంక్చర్ సరిచేయించండి.', 'পাতলা স্পেস-সেভার স্পেয়ার লাগানো? 80 km/h-এর নিচে সোজা টায়ার দোকানে যান। একই দিনে পাংচার ঠিক করান।', 'पातळ स्पेस-सेव्हर स्पेअर लावलाय? 80 km/h पेक्षा कमी वेगाने थेट टायर दुकानात जा. त्याच दिवशी पंक्चर दुरुस्त करा.', 'પાતળી સ્પેસ-સેવર સ્પેર લાગી? 80 km/h થી ઓછી ઝડપે સીધા ટાયર દુકાને જાઓ. તે જ દિવસે પંક્ચર ઠીક કરાવો.', 'ತೆಳುವಾದ ಸ್ಪೇಸ್-ಸೇವರ್ ಸ್ಪೇರ್ ಹಾಕಿದೆಯೇ? 80 km/h ಗಿಂತ ಕಡಿಮೆ ವೇಗದಲ್ಲಿ ನೇರ ಟೈರ್ ಅಂಗಡಿಗೆ ಓಡಿಸಿ. ಅದೇ ದಿನ ಪಂಕ್ಚರ್ ಸರಿಪಡಿಸಿ.', 'നേർത്ത സ്പേസ്-സേവർ സ്പെയർ ഇട്ടോ? 80 km/h ന് താഴെ നേരെ ടയർ കടയിലേക്ക് ഓടിക്കുക. അതേ ദിവസം പഞ്ചർ ശരിയാക്കുക.')
    },
    {
      id: 'car_brake_fail', v: '4w', icon: '🛑',
      name: m('Brake failure / spongy pedal', 'ब्रेक फेल / पैडल ढीला', 'பிரேக் செயலிழப்பு / ஸ்பான்ஜி பெடல்', 'బ్రేక్ విఫలం / స్పాంజీ పెడల్', 'ব্রেক ফেল / নরম প্যাডেল', 'ब्रेक फेल / मऊ पॅडल', 'બ્રેક ફેલ / નરમ પેડલ', 'ಬ್ರೇಕ್ ವಿಫಲ / ಮೆತ್ತನೆ ಪೆಡಲ್', 'ബ്രേക്ക് പരാജയം / മൃദുവായ പെഡൽ'),
      safety: { red: true, warn: m('🔴 DO NOT DRIVE. Pedal to the floor, no bite, or a warning + grinding = stop now. Never DIY brakes on the road.', '🔴 कार न चलाएँ। पैडल फ़र्श तक, पकड़ नहीं, या चेतावनी + घिसने की आवाज़ = अभी रोकें। सड़क पर ब्रेक कभी DIY न करें।', '🔴 காரை ஓட்டாதீர்கள். பெடல் தரை வரை, பிடிப்பு இல்லை, அல்லது எச்சரிக்கை + உராய்வு = இப்போதே நிறுத்துங்கள். சாலையில் பிரேக்கை ஒருபோதும் DIY செய்யாதீர்கள்.', '🔴 కారు నడపవద్దు. పెడల్ నేల వరకు, పట్టు లేదు, లేదా హెచ్చరిక + రాపిడి = ఇప్పుడే ఆపండి. రోడ్డుపై బ్రేక్‌ను ఎప్పుడూ DIY చేయవద్దు.', '🔴 গাড়ি চালাবেন না। প্যাডেল মেঝে পর্যন্ত, ধরছে না, বা সতর্কতা + ঘষা = এখনই থামুন। রাস্তায় ব্রেক কখনও DIY করবেন না।', '🔴 कार चालवू नका. पॅडल जमिनीपर्यंत, पकड नाही, किंवा इशारा + घासणे = आताच थांबा. रस्त्यावर ब्रेक कधीही DIY करू नका.', '🔴 કાર ન ચલાવો. પેડલ ફર્શ સુધી, પકડ નહીં, કે ચેતવણી + ઘસારો = હમણાં જ રોકો. રસ્તા પર બ્રેક ક્યારેય DIY ન કરો.', '🔴 ಕಾರು ಓಡಿಸಬೇಡಿ. ಪೆಡಲ್ ನೆಲದವರೆಗೆ, ಹಿಡಿತ ಇಲ್ಲ, ಅಥವಾ ಎಚ್ಚರಿಕೆ + ಉಜ್ಜುವಿಕೆ = ಈಗಲೇ ನಿಲ್ಲಿಸಿ. ರಸ್ತೆಯಲ್ಲಿ ಬ್ರೇಕ್ ಅನ್ನು ಎಂದಿಗೂ DIY ಮಾಡಬೇಡಿ.', '🔴 കാർ ഓടിക്കരുത്. പെഡൽ തറ വരെ, പിടിത്തമില്ല, അല്ലെങ്കിൽ മുന്നറിയിപ്പ് + ഉരയൽ = ഇപ്പോൾ നിർത്തുക. റോഡിൽ ബ്രേക്ക് ഒരിക്കലും DIY ചെയ്യരുത്.') },
      causes: [
        { name: m('Pedal soft / goes to the floor', 'पैडल नरम / फ़र्श तक जाता है', 'பெடல் மென்மை / தரை வரை செல்கிறது', 'పెడల్ మెత్తగా / నేల వరకు వెళ్తుంది', 'প্যাডেল নরম / মেঝে পর্যন্ত যায়', 'पॅडल मऊ / जमिनीपर्यंत जाते', 'પેડલ નરમ / ફર્શ સુધી જાય', 'ಪೆಡಲ್ ಮೆತ್ತಗೆ / ನೆಲದವರೆಗೆ ಹೋಗುತ್ತದೆ', 'പെഡൽ മൃദു / തറ വരെ പോകുന്നു'), pct: 100, tier: 'red', diff: 10, timeMin: 0,
          tools: m('None — do not attempt', 'कुछ नहीं — कोशिश न करें', 'எதுவும் இல்லை — முயற்சிக்காதீர்கள்', 'ఏమీ లేదు — ప్రయత్నించవద్దు', 'কিছু না — চেষ্টা করবেন না', 'काहीही नाही — प्रयत्न करू नका', 'કંઈ નહીં — પ્રયત્ન ન કરો', 'ಏನೂ ಇಲ್ಲ — ಪ್ರಯತ್ನಿಸಬೇಡಿ', 'ഒന്നുമില്ല — ശ്രമിക്കരുത്'),
          check: m('Spongy/long pedal, brake warning light, or grinding? Stop driving immediately.', 'ढीला/लंबा पैडल, ब्रेक चेतावनी लाइट, या घिसना? तुरंत चलाना बंद करें।', 'ஸ்பான்ஜி/நீளமான பெடல், பிரேக் எச்சரிக்கை விளக்கு, அல்லது உராய்வா? உடனே ஓட்டுவதை நிறுத்துங்கள்.', 'స్పాంజీ/పొడవైన పెడల్, బ్రేక్ హెచ్చరిక లైట్, లేదా రాపిడా? వెంటనే నడపడం ఆపండి.', 'নরম/লম্বা প্যাডেল, ব্রেক সতর্ক লাইট, বা ঘষা? এখনই চালানো বন্ধ করুন।', 'मऊ/लांब पॅडल, ब्रेक इशारा दिवा, किंवा घासणे? लगेच चालवणे थांबवा.', 'નરમ/લાંબું પેડલ, બ્રેક ચેતવણી લાઇટ, કે ઘસારો? તરત જ ચલાવવાનું બંધ કરો.', 'ಮೆತ್ತನೆ/ಉದ್ದ ಪೆಡಲ್, ಬ್ರೇಕ್ ಎಚ್ಚರಿಕೆ ಲೈಟ್, ಅಥವಾ ಉಜ್ಜುವಿಕೆ? ತಕ್ಷಣ ಓಡಿಸುವುದನ್ನು ನಿಲ್ಲಿಸಿ.', 'മൃദുവായ/നീണ്ട പെഡൽ, ബ്രേക്ക് മുന്നറിയിപ്പ് ലൈറ്റ്, അല്ലെങ്കിൽ ഉരയൽ? ഉടനെ ഓടിക്കുന്നത് നിർത്തുക.'),
          steps: [ m('Use engine braking + handbrake gently to slow, pull over, switch off.', 'इंजन ब्रेकिंग + हैंडब्रेक धीरे से लगाकर रोकें, किनारे लें, बंद करें।', 'இன்ஜின் பிரேக்கிங் + ஹேண்ட்பிரேக்கை மெதுவாக பயன்படுத்தி வேகத்தை குறைத்து, ஓரமாக நிறுத்தி, ஆஃப் செய்யுங்கள்.', 'ఇంజిన్ బ్రేకింగ్ + హ్యాండ్‌బ్రేక్‌ను మెల్లగా వాడి వేగం తగ్గించి, పక్కకు ఆపి, ఆఫ్ చేయండి.', 'ইঞ্জিন ব্রেকিং + হ্যান্ডব্রেক আস্তে ব্যবহার করে গতি কমান, পাশে থামুন, বন্ধ করুন।', 'इंजिन ब्रेकिंग + हँडब्रेक हळू वापरून वेग कमी करा, बाजूला थांबा, बंद करा.', 'એન્જિન બ્રેકિંગ + હેન્ડબ્રેક ધીમેથી વાપરી ઝડપ ઘટાડો, બાજુ પર રોકો, બંધ કરો.', 'ಇಂಜಿನ್ ಬ್ರೇಕಿಂಗ್ + ಹ್ಯಾಂಡ್‌ಬ್ರೇಕ್ ಅನ್ನು ಮೆಲ್ಲಗೆ ಬಳಸಿ ವೇಗ ಕಡಿಮೆ ಮಾಡಿ, ಪಕ್ಕಕ್ಕೆ ನಿಲ್ಲಿಸಿ, ಆಫ್ ಮಾಡಿ.', 'എഞ്ചിൻ ബ്രേക്കിംഗ് + ഹാൻഡ്‌ബ്രേക്ക് പതുക്കെ ഉപയോഗിച്ച് വേഗത കുറച്ച്, ഒതുക്കിനിർത്തി, ഓഫ് ചെയ്യുക.'), m('Do not drive. Brakes are never a roadside fix.', 'न चलाएँ। ब्रेक कभी सड़क किनारे ठीक नहीं होते।', 'ஓட்டாதீர்கள். பிரேக் ஒருபோதும் சாலையோர பழுதுபார்ப்பு அல்ல.', 'నడపవద్దు. బ్రేక్ ఎప్పటికీ రోడ్డు పక్క మరమ్మతు కాదు.', 'চালাবেন না। ব্রেক কখনও রাস্তার পাশে ঠিক হয় না।', 'चालवू नका. ब्रेक कधीही रस्त्याकडेची दुरुस्ती नाही.', 'ન ચલાવો. બ્રેક ક્યારેય રસ્તાની બાજુએ ઠીક થતા નથી.', 'ಓಡಿಸಬೇಡಿ. ಬ್ರೇಕ್ ಎಂದಿಗೂ ರಸ್ತೆಬದಿ ದುರಸ್ತಿ ಅಲ್ಲ.', 'ഓടിക്കരുത്. ബ്രേക്ക് ഒരിക്കലും റോഡരികിലെ പരിഹാരമല്ല.') ],
          ifFails: m('', ''), mechCost: '₹800–₹15,000' }
      ],
      towMsg: m('🔴 Tow only. SOS family. The fair repair band is shown above so the workshop can\'t inflate it — but the car moves on a flatbed, not its own wheels.', '🔴 सिर्फ़ टो। SOS करें। सही मरम्मत बैंड ऊपर है ताकि दुकान बढ़ा न सके — पर कार फ्लैटबेड पर जाए, अपने पहियों पर नहीं।', '🔴 டோ மட்டுமே. குடும்பத்திற்கு SOS செய்யுங்கள். சரியான பழுது விலை மேலே காட்டப்பட்டுள்ளது, கடை அதிகப்படுத்த முடியாது — ஆனால் கார் ஃப்ளாட்பெட்டில் செல்ல வேண்டும், அதன் சக்கரங்களில் அல்ல.', '🔴 టో మాత్రమే. కుటుంబానికి SOS చేయండి. సరైన మరమ్మతు ధర పైన చూపబడింది, షాప్ పెంచలేదు — కానీ కారు ఫ్లాట్‌బెడ్‌పై వెళ్తుంది, దాని చక్రాలపై కాదు.', '🔴 শুধু টো। পরিবারকে SOS করুন। সঠিক মেরামতের দাম উপরে দেখানো আছে যাতে দোকান বাড়াতে না পারে — কিন্তু গাড়ি ফ্ল্যাটবেডে যাবে, নিজের চাকায় নয়।', '🔴 फक्त टो. कुटुंबाला SOS करा. योग्य दुरुस्ती किंमत वर दाखवली आहे जेणेकरून दुकान वाढवू शकणार नाही — पण कार फ्लॅटबेडवर जावी, स्वतःच्या चाकांवर नाही.', '🔴 માત્ર ટો. પરિવારને SOS કરો. યોગ્ય રિપેર ભાવ ઉપર બતાવ્યો છે જેથી દુકાન વધારી ન શકે — પણ કાર ફ્લેટબેડ પર જાય, પોતાના પૈડાં પર નહીં.', '🔴 ಟೋ ಮಾತ್ರ. ಕುಟುಂಬಕ್ಕೆ SOS ಮಾಡಿ. ಸರಿಯಾದ ದುರಸ್ತಿ ದರ ಮೇಲೆ ತೋರಿಸಲಾಗಿದೆ, ಅಂಗಡಿ ಹೆಚ್ಚಿಸಲಾಗದು — ಆದರೆ ಕಾರು ಫ್ಲ್ಯಾಟ್‌ಬೆಡ್‌ನಲ್ಲಿ ಹೋಗಬೇಕು, ತನ್ನ ಚಕ್ರಗಳ ಮೇಲೆ ಅಲ್ಲ.', '🔴 ടോ മാത്രം. കുടുംബത്തിന് SOS ചെയ്യുക. ശരിയായ റിപ്പയർ വില മുകളിൽ കാണിച്ചിട്ടുണ്ട്, കട കൂട്ടാനാകില്ല — പക്ഷേ കാർ ഫ്ലാറ്റ്ബെഡിൽ പോകണം, സ്വന്തം ചക്രങ്ങളിലല്ല.')
    }
  ];

